function dedupe(arr) {
  var seen = {};
  var result = [];
  for (var i = 0; i < arr.length; i++) {
    var obj = arr[i];
    if (obj === null || typeof obj !== 'object') {
      result.push(obj);
      continue;
    }
    var keys = Object.keys(obj).sort();
    var json = '{' + keys.map(function (k) {
      return JSON.stringify(k) + ':' + JSON.stringify(obj[k]);
    }).join(',') + '}';
    if (!seen[json]) {
      seen[json] = true;
      result.push(obj);
    }
  }
  return result;
}

